def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def claim(cid,statement,hypotheses,proof,dependencies):
    obj={'claim_id':cid,'version':1,'exact_statement':statement,'hypotheses':hypotheses,'statement_sha256':hashlib.sha256(json.dumps({'statement':statement,'hypotheses':hypotheses},sort_keys=True,separators=(',',':')).encode()).hexdigest(),'contributors':['account05/A003'],'proof_source':{'run_id':ROOT.name,'path':'REPORT.md','locator':proof},'proof_dependencies':dependencies,'review_records':[],'status':'AUTHOR_PROVED_PENDING_INDEPENDENT_REVIEW','supersedes':[],'refutes':[],'first_unproved_line':None,'next_consumers':['A006','A026','A034','A005','A086','A094','B20']}
    assert set(obj)==set(protocol['required_per_run']['claim_fields'])
    return obj
